 void editLast(){if(game.drawn.isEmpty()){toast("Aucun tirage à modifier");return;}int old=game.drawn.get(game.drawn.size()-1);EditText field=new EditText(this);field.setInputType(2);field.setText(""+old);field.selectAll();new AlertDialog.Builder(this).setTitle("Modifier le dernier numéro : "+old).setView(field).setNegativeButton("Annuler",null).setPositiveButton("Valider",(d,w)->{try{game.replace(old,Integer.parseInt(field.getText().toString()));digits="";save();render();}catch(Exception e){toast("Numéro invalide ou déjà tiré");}}).show();}
 void recordStage(int newMode){if(newMode>game.mode){for(int stage=game.mode;stage<newMode;stage++){externalWins.add("Gain extérieur "+stage+" ligne"+(stage>1?"s":"")+" : "+missingSnapshot(stage));}}game.mode=newMode;save();render();}
 String missingSnapshot(int stage){if(game.cards.isEmpty())return "aucun carton importé";int best=99;Game.Card nearest=null;int[] lines=null;for(Game.Card c:game.cards){int[] misses=new int[3];for(int r=0;r<3;r++)for(int n:c.grid[r])if(n>0&&!game.drawn.contains(n))misses[r]++;Arrays.sort(misses);int total=misses[0]+(stage>=2?misses[1]:0)+(stage==3?misses[2]:0);if(total<best){best=total;nearest=c;}}if(nearest==null)return "aucun carton";ArrayList<ArrayList<Integer>> rows=new ArrayList<>();for(int r=0;r<3;r++){ArrayList<Integer> missing=new ArrayList<>();for(int n:nearest.grid[r])if(n>0&&!game.drawn.contains(n))missing.add(n);rows.add(missing);}rows.sort((x,y)->Integer.compare(x.size(),y.size()));ArrayList<Integer> needed=new ArrayList<>();for(int r=0;r<stage;r++)needed.addAll(rows.get(r));Collections.sort(needed);return "carton "+nearest.id+", "+best+" manquant(s) : "+needed.toString();}

